SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

START TRANSACTION;

SET @xgsz_upgrade = NOT EXISTS (SELECT 1 FROM site_metadata WHERE name='company-offerings-20261109');

UPDATE site_page SET payload=JSON_SET(payload, '$.capabilities', CAST(CONVERT(X'' USING utf8mb4) AS JSON), '$.heroNote', '服务器整机 / 本地化部署 / 推理优化 / 集群交付运维维保'),version=version+1 WHERE id='home' AND @xgsz_upgrade;

UPDATE site_page SET payload=JSON_SET(payload, '$.footerNote', '服务器整机 · 本地化部署 · 推理优化 · 集群交付运维维保'),version=version+1 WHERE id='global' AND @xgsz_upgrade;

UPDATE site_page SET payload=JSON_MERGE_PATCH(CAST(CONVERT(X'' USING utf8mb4) AS JSON),payload),version=version+1 WHERE id='products' AND @xgsz_upgrade;

UPDATE site_page SET payload=JSON_MERGE_PATCH(CAST(CONVERT(X'' USING utf8mb4) AS JSON),payload),version=version+1 WHERE id='about' AND @xgsz_upgrade;

INSERT INTO site_content(id,kind,payload,version) SELECT 'site-settings','settings',CONVERT(X'7b2270686f6e65223a223138343538303535323936222c22656d61696c223a22222c2261646472657373223a22222c227765636f6d4e616d65223a22222c227765636f6d55726c223a22222c227765636f6d5172223a22227d' USING utf8mb4),1 WHERE @xgsz_upgrade AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='site-settings');

UPDATE site_content SET payload=JSON_SET(payload,'$.phone','18458055296'),version=version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE id='site-settings' AND @xgsz_upgrade;

UPDATE BasicInformation SET phone='18458055296' WHERE isDeleted=0 AND id=(SELECT identifier FROM (SELECT MIN(id) AS identifier FROM BasicInformation WHERE isDeleted=0) AS selected) AND @xgsz_upgrade;

UPDATE site_catalog_meta SET version=version+1 WHERE kind='basicInformation' AND record_id=(SELECT MIN(id) FROM BasicInformation WHERE isDeleted=0) AND @xgsz_upgrade;

INSERT INTO site_metadata(name,content_value) SELECT 'company-offerings-20261109','complete' WHERE @xgsz_upgrade;

COMMIT;
